-- Abyssea Tracker progression database v0.9.8
-- UI sorts every NM alphabetically regardless of declaration order.
-- requirement.type: 'item' = physical pop item; 'ki' = key item.
-- rewards are progression-relevant KIs/items, not general equipment drops.

local function nm(name, spawn_type, requirements, rewards, location, respawn, source_note)
    return {
        name = name, spawn_type = spawn_type, requirements = requirements or {}, rewards = rewards or {},
        location = location, respawn = respawn, source_note = source_note,
    };
end
local function item(name, source) return { type = 'item', name = name, source = source }; end
local function ki(name, source) return { type = 'ki', name = name, source = source }; end
local function rki(name, used_for) return { type = 'ki', name = name, used_for = used_for }; end

